namespace {
float number(jass::Real value){return std::bit_cast<float>(value.bits());}
jass::Real real(float value){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(value));}
unsigned count(float value,unsigned maximum){if(value<0 || value>maximum || value!=std::floor(value))throw std::runtime_error("Alchemist source count outside supported range");return unsigned(value);}
}
void ScriptSession::alchemistSpellInfo(SpellInfo& s){
    auto field=[&](const char* name){return definitions().number(s.ability,"AbilityData",std::string(name)+std::to_string(s.level));};
    if(s.kind==SpellKind::HealingSpray){s.period=s.secondary;s.shards=count(s.loss,128);s.maxDamage=field("DataD");s.buildingFactor=field("DataE");s.pulses=count(field("DataF"),1024);s.channelled=s.animationLooping=true;s.channelTime=s.pulses*s.period;if(!s.pulses || !s.shards || s.period<1.f/1024 || s.period>300 || s.area<=0 || s.speed<=0 || s.missile.empty() || s.amount<0 || s.amount>1000000 || s.maxDamage<0 || s.maxDamage>1000000000)throw std::runtime_error("Invalid Healing Spray wave schedule or source missile");}
    if(s.kind==SpellKind::AcidBomb){s.moveReduction=s.amount;s.attackReduction=s.secondary;s.initialDamage=field("DataD");s.extraDamage=field("DataE");s.period=field("DataF");if(!s.buff || s.loss<0 || s.loss>1000000 || s.duration<=0 || s.heroDuration<0 || s.period<1.f/1024 || s.period>300 || s.initialDamage<0 || s.initialDamage>1000000 || s.extraDamage<0 || s.extraDamage>1000000)throw std::runtime_error("Invalid Acid Bomb armor, duration or periodic damage");}
    if(s.kind==SpellKind::Transmute){s.creepLevel=count(s.loss,100);s.allowBounty=count(field("DataD"),1)!=0;if(s.amount<0 || s.amount>1000 || s.secondary<0 || s.secondary>1000)throw std::runtime_error("Invalid Transmute resource factors");}
}
void ScriptSession::healingSprayPulse(std::uint32_t id,const CastOrder& cast){
    if(!alive(id,NativeKind::Unit))return;auto u=units_.at(id);if(u->removing || !u->cast || u->cast->ticket!=cast.ticket || u->owner!=cast.owner || number(u->life)<=0)return;if(healingSprays_.size()>=4096)throw std::runtime_error("Healing Spray wave budget exceeded");auto& s=cast.spell;HealingSprayWave wave;wave.spell=s;wave.source=id;wave.owner=cast.owner;wave.origin={u->x,u->y};wave.point=cast.point;wave.height=u->displayFlyHeight()+definitions().number(u->type,"UnitWeapons","launchZ",60);wave.duration=std::max(1.f/32,std::hypot(number(cast.point.x)-number(u->x),number(cast.point.y)-number(u->y))/s.speed);
    for(unsigned i=0;i<s.shards;++i){float angle=float(double(random())/4294967296.*6.28318530718),radius=std::sqrt(float(double(random())/4294967296.))*s.area;SprayBottle bottle;bottle.endpoint=requireWorld().clamp({real(number(cast.point.x)+std::cos(angle)*radius),real(number(cast.point.y)+std::sin(angle)*radius)});bottle.distance=std::hypot(number(bottle.endpoint.x)-number(wave.origin.x),number(bottle.endpoint.y)-number(wave.origin.y));bottle.effect=createEffect(s.missile,wave.origin,0,{},false).bits;if(bottle.effect){auto effect=effects_.at(bottle.effect);effect->z=wave.height;effect->facing=std::atan2(number(bottle.endpoint.y)-number(wave.origin.y),number(bottle.endpoint.x)-number(wave.origin.x));}wave.bottles.push_back(bottle);}healingSprays_.emplace(++spellTicket_,std::move(wave));
}
void ScriptSession::healingSprayImpact(const HealingSprayWave& wave){
    UnitState retained;retained.handle=wave.source;retained.owner=wave.owner;auto& s=wave.spell;std::vector<std::pair<float,std::uint32_t>> choices;for(auto& [id,u]:units_){float distance=std::hypot(number(u->x)-number(wave.point.x),number(u->y)-number(wave.point.y));if(distance<=s.area+u->collision && spellTarget(retained,*u,s,false,wave.owner) && number(u->life)<number(u->maxLife))choices.emplace_back(distance,id);}std::sort(choices.begin(),choices.end());float allocated=0;auto visual=s;visual.ability=s.effectAlias;
    for(auto [distance,id]:choices){if(!alive(id,NativeKind::Unit))continue;auto u=units_.at(id);if(!spellTarget(retained,*u,s,false,wave.owner) || std::hypot(number(u->x)-number(wave.point.x),number(u->y)-number(wave.point.y))>s.area+u->collision)continue;float healing=std::min(std::max(0.f,number(u->maxLife)-number(u->life)),spellHealAmount(*u,s.amount*(u->building?s.buildingFactor:1)));if(s.maxDamage>0)healing=std::min(healing,std::max(0.f,s.maxDamage-allocated));if(healing<=0)continue;allocated+=healing;unitLife(runtime_.handle("unit",id),real(number(u->life)+healing));if(s.effectAlias && alive(id,NativeKind::Unit) && !u->removing && number(u->life)>0)spellVisual(visual,"Specialart",id,{u->x,u->y});}
}
void ScriptSession::healingSpraysTick(double delta){
    std::vector<std::uint64_t> waves;for(auto& [id,wave]:healingSprays_)waves.push_back(id);for(auto id:waves){auto found=healingSprays_.find(id);if(found==healingSprays_.end())continue;auto wave=std::move(found->second);healingSprays_.erase(found);wave.elapsed+=delta;bool complete=true;for(auto& bottle:wave.bottles){float duration=std::max(1.f/32,bottle.distance/wave.spell.speed),fraction=std::clamp(float(wave.elapsed)/duration,0.f,1.f);complete&=fraction>=1;if(auto effect=effects_.find(bottle.effect);effect!=effects_.end()){effect->second->point={real(number(wave.origin.x)+(number(bottle.endpoint.x)-number(wave.origin.x))*fraction),real(number(wave.origin.y)+(number(bottle.endpoint.y)-number(wave.origin.y))*fraction)};effect->second->z=wave.height*(1-fraction)+wave.spell.missileArc*bottle.distance*std::sin(3.14159265359f*fraction);}if(fraction>=1 && bottle.effect){destroyEffect(bottle.effect);bottle.effect=0;}}if(!wave.delivered && wave.elapsed+1e-7>=wave.duration){wave.delivered=true;healingSprayImpact(wave);}if(!complete || !wave.delivered)healingSprays_.emplace(id,std::move(wave));}
}
bool ScriptSession::alchemistImpact(const SpellMissile& missile){
    auto& s=missile.spell;if(s.kind!=SpellKind::AcidBomb && s.kind!=SpellKind::Transmute)return false;if(!alive(missile.source,NativeKind::Unit) || !alive(missile.target,NativeKind::Unit))return true;auto caster=units_.at(missile.source),target=units_.at(missile.target);if(!spellTarget(*caster,*target,s,false,missile.owner))return true;if(s.kind==SpellKind::Transmute){transmute(missile.source,missile.target,s,missile.owner);return true;}
    WorldPoint point{target->x,target->y};auto choices=spellTargets(missile.source,s,point,missile.owner);auto poison=s;poison.armor=-s.loss;for(auto id:choices){if(!alive(id,NativeKind::Unit))continue;auto u=units_.at(id);if(!spellTarget(*caster,*u,s,false,missile.owner))continue;auto old=u->buffs.find(s.buff);double phase=old!=u->buffs.end() && old->second.kind==BuffKind::AcidBomb?old->second.period:0;applyBuff(id,missile.source,poison,BuffKind::AcidBomb);auto found=u->buffs.find(s.buff);if(found==u->buffs.end() || found->second.kind!=BuffKind::AcidBomb)continue;auto& b=found->second;b.damage=(id==missile.target?s.initialDamage:s.extraDamage)*s.period;b.tickInterval=s.period;b.period=phase;b.moveReduction=s.moveReduction;b.attackReduction=s.attackReduction;b.originAbility=s.ability;b.sourceLevel=s.level;b.sourceOwner=missile.owner;}return true;
}
float ScriptSession::acidBombTick(UnitBuff& buff,double elapsed){
    if(buff.kind!=BuffKind::AcidBomb)return 0;if(buff.tickInterval<=0)throw std::runtime_error("Acid Bomb lost its source interval");buff.period+=elapsed;float damage=0;while(buff.period+1e-7>=buff.tickInterval){buff.period=std::max(0.,buff.period-buff.tickInterval);damage+=buff.damage;}return damage;
}
void ScriptSession::transmute(std::uint32_t source,std::uint32_t id,const SpellInfo& s,unsigned owner){
    if(owner>=16 || !alive(source,NativeKind::Unit) || !alive(id,NativeKind::Unit))return;auto u=units_.at(id);if(!spellTarget(*units_.at(source),*u,s,false,owner))return;auto victim=*u;auto revision=u->deathRevision;auto reward=[&](const char* field,float factor){double value=definitions().number(victim.type,"UnitBalance",field)*double(factor);if(!std::isfinite(value) || value<0 || value>INT_MAX)throw std::runtime_error("Transmute reward outside supported resource range");return victim.illusion?0:int(value);};int gold=reward("goldcost",s.amount),lumber=reward("lumbercost",s.secondary);unitLife(runtime_.handle("unit",id),{},source,s.allowBounty);if(u->deathRevision!=revision+1 || number(u->life)>0 || u->rebirth || u->phoenixCycle)return;if(!u->removing && alive(id,NativeKind::Unit)){if(u->corpse){u->corpse->consumed=true;u->corpse->flags=0;u->corpse->gone=true;}u->exploded=true;++fogRevision_;}auto art=s;art.ability=s.buff;spellVisual(art,"Specialart",0,{victim.x,victim.y});creditKillResources(owner,gold,lumber);
}
void ScriptSession::creditKillResources(unsigned owner,int gold,int lumber){
    if(owner>=16 || gold<0 || lumber<0)throw std::runtime_error("Invalid kill reward");auto& states=config_.players[owner].states;for(auto [field,amount]:{std::pair{1u,gold},std::pair{2u,lumber}}){int before=states[field],after=states[field]=int(std::min(std::int64_t(INT_MAX),std::int64_t(before)+amount));if(after!=before)playerChange(owner,field,before,after,false);}
}
void ScriptSession::awardKillBounty(std::uint32_t killer,const UnitState& victim){
    if(victim.illusion || !alive(killer,NativeKind::Unit) || victim.owner>=16)return;auto source=units_.at(killer);auto owner=source->owner;auto& states=config_.players[victim.owner].states;auto enabled=states.find(7);if(owner>=16 || source->removing || !enemy(owner,victim.owner) || enabled==states.end() || !enabled->second)return;auto roll=[&](const char* prefix){auto key=std::string(prefix);auto& data=definitions();unsigned dice=count(data.number(victim.type,"UnitBalance",key+"dice"),1000),sides=count(data.number(victim.type,"UnitBalance",key+"sides"),1000000);std::int64_t amount=count(data.number(victim.type,"UnitBalance",key+"plus"),1000000000);if(dice && !sides)throw std::runtime_error("Kill bounty dice require source sides");for(unsigned i=0;i<dice;++i)amount+=random()%sides+1;return int(std::min(std::int64_t(INT_MAX),amount));};int gold=roll("bounty"),lumber=roll("lumberbounty");creditKillResources(owner,gold,lumber);
}
